#include <cstdio>
#include <vector>
#include <string>
#include <map>
#include <functional>
using namespace std;

enum Color { WHITE, GRAY, BLACK };

int main() {
    vector<string> names = {"u", "v", "w", "x", "y", "z"};
    map<string, int> idx;
    for (int i = 0; i < (int)names.size(); i++) idx[names[i]] = i;
    int n = names.size();
    vector<vector<int>> adj(n);
    auto addEdge = [&](string a, string b) { adj[idx[a]].push_back(idx[b]); };
    addEdge("u", "v"); addEdge("u", "x"); addEdge("v", "y");
    addEdge("w", "y"); addEdge("w", "z"); addEdge("x", "v");
    addEdge("y", "x"); addEdge("z", "z");

    vector<Color> color(n, WHITE);
    vector<int> disc(n), fin(n);
    int clock_ = 0;

    function<void(int)> visit = [&](int u) {
        color[u] = GRAY;
        disc[u] = ++clock_;
        for (int v : adj[u]) {
            if (color[v] == WHITE) {
                printf("%s->%s: tree\n", names[u].c_str(), names[v].c_str());
                visit(v);
            } else if (color[v] == GRAY) {
                printf("%s->%s: back\n", names[u].c_str(), names[v].c_str());
            } else if (disc[u] < disc[v]) {
                printf("%s->%s: forward\n", names[u].c_str(), names[v].c_str());
            } else {
                printf("%s->%s: cross\n", names[u].c_str(), names[v].c_str());
            }
        }
        color[u] = BLACK;
        fin[u] = ++clock_;
    };

    for (int u = 0; u < n; u++)
        if (color[u] == WHITE) visit(u);

    for (int u = 0; u < n; u++)
        printf("%s: d=%d f=%d\n", names[u].c_str(), disc[u], fin[u]);
    return 0;
}
